"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[2422],{22422:e=>{e.exports=JSON.parse('{"categories":{"prayer-times":"Heures de pri\xe8re","location":"Localisation","setup":"Vos r\xe9glages de pri\xe8re","athan":"Adhan","scheduled":"Adhan automatique","quran":"Coran et lecture","hifz":"Hifz Coach","masjid":"Ma mosqu\xe9e","ramadan":"Ramadan","islamic-calendar":"Qibla et calendrier islamique","fasting":"Je\xfbnes de la Sunna","remembrance":"Adhkar, tasbih et rappels quotidiens","help":"Premiers pas"},"commands":{"Alexa, ask Muslim Companion what is my next prayer":{"does":"Donne la prochaine pri\xe8re, son heure et le temps restant, ainsi que l\'iqama de votre mosqu\xe9e si vous en suivez une.","say":["Alexa, demande \xe0 Muslim Companion quelle est ma prochaine pri\xe8re","Alexa, demande \xe0 Muslim Companion quand est la prochaine pri\xe8re"]},"Alexa, ask Muslim Companion when is Maghrib":{"does":"Donne l\'heure d\'une pri\xe8re aujourd\'hui (apr\xe8s Isha, Fajr est celle de demain).","say":["Alexa, demande \xe0 Muslim Companion quand est Maghrib","Alexa, demande \xe0 Muslim Companion \xe0 quelle heure est Fajr"]},"Alexa, ask Muslim Companion for today\'s prayer times":{"does":"Lit toutes les heures du jour. Sur un Echo Show, elles s\'affichent aussi avec la prochaine pri\xe8re et un compte \xe0 rebours.","say":["Alexa, demande \xe0 Muslim Companion les heures de pri\xe8re d\'aujourd\'hui","Alexa, demande \xe0 Muslim Companion les heures de pri\xe8re"]},"Alexa, ask Muslim Companion to use my Echo\'s location":{"does":"R\xe8gle vos heures de pri\xe8re \xe0 partir de l\'adresse de votre Echo (apr\xe8s avoir autoris\xe9 l\'adresse de l\'appareil dans l\'app Alexa). Seules la ville et des coordonn\xe9es approximatives sont conserv\xe9es.","say":["Alexa, demande \xe0 Muslim Companion d\'utiliser la position de mon Echo","Alexa, demande \xe0 Muslim Companion de mettre \xe0 jour ma position"]},"Alexa, ask Muslim Companion for prayer times where I am":{"does":"Dans l\'app Alexa sur votre t\xe9l\xe9phone : les heures de pri\xe8re l\xe0 o\xf9 vous \xeates, pour cette r\xe9ponse seulement. Vos Adhans \xe0 la maison ne changent pas.","say":["Alexa, demande \xe0 Muslim Companion les heures de pri\xe8re l\xe0 o\xf9 je suis","Alexa, demande \xe0 Muslim Companion les heures de pri\xe8re pr\xe8s de moi"]},"Yes":{"does":"R\xe9pond \xe0 une question de Muslim Companion, par exemple s\'il faut utiliser la position de votre Echo.","say":["Oui","Non"]},"Alexa, ask Muslim Companion to read my prayer settings":{"does":"Donne votre position, votre m\xe9thode de calcul et votre madhab pour Asr, et comment les changer.","say":["Alexa, demande \xe0 Muslim Companion de lire mes r\xe9glages de pri\xe8re"]},"Alexa, ask Muslim Companion to set my calculation method to Umm al-Qura":{"does":"Change le calcul de vos heures de pri\xe8re : ISNA, Ligue islamique mondiale, Umm al-Qura, \xc9gypte, Karachi, Golfe, Kowe\xeft, Qatar, Singapour, France, Turquie, Russie, T\xe9h\xe9ran ou Jafari. Alexa confirme avec votre nouvelle prochaine pri\xe8re et explique comment revenir en arri\xe8re.","say":["Alexa, demande \xe0 Muslim Companion de r\xe9gler ma m\xe9thode de calcul sur Umm al-Qura","Alexa, dis \xe0 Muslim Companion d\'utiliser la m\xe9thode de la Ligue islamique mondiale","Alexa, dis \xe0 Muslim Companion que ma mosqu\xe9e utilise ISNA"]},"Alexa, ask Muslim Companion to set my madhab to Hanafi":{"does":"R\xe8gle l\'heure d\'Asr : hanafite (Asr plus tard), ou standard pour les chaf\xe9ites, malikites et hanbalites.","say":["Alexa, demande \xe0 Muslim Companion de r\xe9gler mon madhab sur hanafite","Alexa, dis \xe0 Muslim Companion que je suis le madhab hanafite","Alexa, demande \xe0 Muslim Companion de r\xe9gler mon madhab sur standard"]},"Alexa, ask Muslim Companion which calculation method should I use":{"does":"Propose la m\xe9thode la plus utilis\xe9e l\xe0 o\xf9 vous vivez (par exemple ISNA en Am\xe9rique du Nord, la Diyanet en Turquie) et offre de changer : r\xe9pondez oui ou non.","say":["Alexa, demande \xe0 Muslim Companion quelle m\xe9thode de calcul je devrais utiliser"]},"Alexa, ask Muslim Companion what calculation method am I using":{"does":"D\'autres fa\xe7ons de demander vos r\xe9glages.","say":["Alexa, demande \xe0 Muslim Companion quelle m\xe9thode de calcul j\'utilise","Alexa, demande \xe0 Muslim Companion quel est mon madhab"]},"Alexa, ask Muslim Companion to play athan":{"does":"Joue l\'Adhan maintenant, suivi des douas et du Coran choisis. Voix possibles : La Mecque, M\xe9dine, Mishary, Zahrani\u2026","say":["Alexa, demande \xe0 Muslim Companion de jouer l\'adhan","Alexa, demande \xe0 Muslim Companion de jouer l\'adhan de La Mecque"]},"Alexa, ask Muslim Companion to play fajr athan":{"does":"Joue l\'Adhan de cette pri\xe8re (Fajr a sa propre voix).","say":["Alexa, demande \xe0 Muslim Companion de jouer l\'adhan de fajr","Alexa, demande \xe0 Muslim Companion de jouer l\'adhan de maghrib"]},"Alexa, ask Muslim Companion to test athan":{"does":"Joue l\'Adhan une fois pour v\xe9rifier le son de cet Echo.","say":["Alexa, demande \xe0 Muslim Companion de tester l\'adhan"]},"Alexa, ask Muslim Companion what is my scheduled athan status":{"does":"Indique si l\'Adhan automatique est activ\xe9.","say":["Alexa, demande \xe0 Muslim Companion l\'\xe9tat de mon adhan programm\xe9"]},"Alexa, ask Muslim Companion to enable scheduled athan":{"does":"Active l\'Adhan automatique. Il est jou\xe9 \xe0 chaque pri\xe8re via votre routine Alexa (voir le guide d\'installation).","say":["Alexa, demande \xe0 Muslim Companion d\'activer l\'adhan programm\xe9"]},"Alexa, ask Muslim Companion to disable scheduled athan":{"does":"D\xe9sactive l\'Adhan automatique pour toutes les pri\xe8res jusqu\'\xe0 ce que vous le r\xe9activiez.","say":["Alexa, demande \xe0 Muslim Companion de d\xe9sactiver l\'adhan programm\xe9"]},"Alexa, ask Muslim Companion to play Surah Al-Kahf":{"does":"Joue n\'importe quelle sourate par son nom ou son num\xe9ro, dite \xe0 votre fa\xe7on (Fatiha ou Fateha, Baqarah ou Baqara, Nisa\u2026), avec votre r\xe9citateur ou celui que vous nommez (Qari Badar, Maher, Al-Muaiqly, Soudais\u2026), ou avec une traduction anglaise ou ourdoue apr\xe8s chaque verset.","say":["Alexa, demande \xe0 Muslim Companion de jouer la sourate Al-Kahf","Alexa, demande \xe0 Muslim Companion de jouer la sourate Baqarah par Qari Badar","Alexa, demande \xe0 Muslim Companion de jouer la Fatiha par Maher","Alexa, demande \xe0 Muslim Companion de jouer la sourate num\xe9ro 36","Alexa, demande \xe0 Muslim Companion de jouer la sourate Yasin avec traduction anglaise"]},"Alexa, ask Muslim Companion which reciters do you have":{"does":"Liste les r\xe9citateurs, ou ceux dont le nom commence par une lettre. Si Alexa ne conna\xeet pas le r\xe9citateur nomm\xe9, elle propose ceux qui commencent par la m\xeame lettre.","say":["Alexa, demande \xe0 Muslim Companion quels r\xe9citateurs tu as","Alexa, demande \xe0 Muslim Companion quels r\xe9citateurs commencent par S"]},"Alexa, ask Muslim Companion to turn on Friday Kahf":{"does":"Chaque vendredi, la sourate Al-Kahf est jou\xe9e apr\xe8s l\'Adhan de Fajr (ou Dhuhr, r\xe9glable sur le tableau de bord).","say":["Alexa, demande \xe0 Muslim Companion d\'activer Al-Kahf du vendredi","Alexa, demande \xe0 Muslim Companion de d\xe9sactiver Al-Kahf du vendredi"]},"Alexa, next":{"does":"Pendant le Coran : sourate suivante ou pr\xe9c\xe9dente. Pendant l\'Adhan et les douas, \xab suivant \xbb passe \xe0 la suite.","say":["Alexa, suivant","Alexa, pr\xe9c\xe9dent"]},"Alexa, start over":{"does":"Reprend la sourate en cours depuis le d\xe9but.","say":["Alexa, recommence"]},"Alexa, pause":{"does":"Met la r\xe9citation en pause et reprend au m\xeame endroit.","say":["Alexa, pause","Alexa, reprends"]},"Alexa, stop":{"does":"Arr\xeate l\'Adhan ou la r\xe9citation \xe0 tout moment.","say":["Alexa, stop","Alexa, annule"]},"Alexa, ask Muslim Companion how far am I in the Quran":{"does":"Donne votre parcours coranique : temps d\'\xe9coute et part du khatm d\xe9j\xe0 \xe9cout\xe9e.","say":["Alexa, demande \xe0 Muslim Companion o\xf9 j\'en suis dans le Coran"]},"Alexa, shuffle":{"does":"Explique comment choisir le Coran al\xe9atoire ou continu sur la page Programme du Coran.","say":["Alexa, al\xe9atoire","Alexa, en boucle"]},"Alexa, ask Muslim Companion to start Hifz":{"does":"Joue votre le\xe7on actuelle : chaque verset r\xe9p\xe9t\xe9, puis toute la le\xe7on. Sur un Echo Show, le verset s\'affiche.","say":["Alexa, demande \xe0 Muslim Companion de commencer le Hifz"]},"Alexa, tell Muslim Companion I memorized it":{"does":"Marque la le\xe7on comme m\xe9moris\xe9e et passe \xe0 la suivante.","say":["Alexa, dis \xe0 Muslim Companion que je l\'ai m\xe9moris\xe9e"]},"Alexa, ask Muslim Companion to repeat each ayah five times":{"does":"R\xe8gle le nombre de r\xe9p\xe9titions de chaque verset : 1, 3, 5, 7 ou 10.","say":["Alexa, demande \xe0 Muslim Companion de r\xe9p\xe9ter chaque verset cinq fois"]},"Alexa, ask Muslim Companion how is my Hifz":{"does":"Indique combien de versets vous avez m\xe9moris\xe9s et votre le\xe7on actuelle.","say":["Alexa, demande \xe0 Muslim Companion o\xf9 en est mon Hifz"]},"Alexa, ask Muslim Companion when is iqamah":{"does":"Donne la prochaine iqama \xe0 la mosqu\xe9e que vous suivez.","say":["Alexa, demande \xe0 Muslim Companion quand est l\'iqama"]},"Alexa, ask Muslim Companion when is jumuah":{"does":"Donne l\'heure ou les heures de la Joumou\'a de cette semaine \xe0 votre mosqu\xe9e.","say":["Alexa, demande \xe0 Muslim Companion quand est la Joumou\'a"]},"Alexa, ask Muslim Companion to turn on Ramadan mode":{"does":"Active ou d\xe9sactive le mode Ramadan : rappel du suhour, iftar \xe0 Maghrib et r\xe9citation des Tarawih apr\xe8s Isha.","say":["Alexa, demande \xe0 Muslim Companion d\'activer le mode Ramadan","Alexa, demande \xe0 Muslim Companion de d\xe9sactiver le mode Ramadan"]},"Alexa, ask Muslim Companion is Ramadan mode on":{"does":"Indique si le mode Ramadan est activ\xe9.","say":["Alexa, demande \xe0 Muslim Companion si le mode Ramadan est activ\xe9"]},"Alexa, ask Muslim Companion when is suhoor":{"does":"Donne la fin du suhour (Fajr) et l\'heure de l\'iftar (Maghrib).","say":["Alexa, demande \xe0 Muslim Companion quand finit le suhour","Alexa, demande \xe0 Muslim Companion quand est l\'iftar"]},"Alexa, ask Muslim Companion which way is the Qibla":{"does":"Donne la direction de la Qibla depuis votre position, en degr\xe9s par rapport au nord g\xe9ographique et en point cardinal, et la distance jusqu\'\xe0 La Mecque.","say":["Alexa, demande \xe0 Muslim Companion dans quelle direction est la Qibla","Alexa, demande \xe0 Muslim Companion o\xf9 est la Qibla"]},"Alexa, ask Muslim Companion what is the Hijri date":{"does":"Donne la date h\xe9girienne du jour (la m\xeame que l\'app et votre Echo Show) et s\'il s\'agit d\'un jour particulier.","say":["Alexa, demande \xe0 Muslim Companion quelle est la date h\xe9girienne","Alexa, demande \xe0 Muslim Companion quelle est la date islamique aujourd\'hui"]},"Alexa, ask Muslim Companion when is Ramadan":{"does":"Quand tombent le Ramadan, l\'A\xefd, Achoura, Arafat, le Nouvel An islamique, les dix derni\xe8res nuits ou les jours blancs, avec un compte \xe0 rebours. Les dates suivent Umm al-Qura et peuvent diff\xe9rer d\'un jour l\xe0 o\xf9 la lune est observ\xe9e localement.","say":["Alexa, demande \xe0 Muslim Companion quand commence le Ramadan","Alexa, demande \xe0 Muslim Companion combien de jours avant l\'A\xefd","Alexa, demande \xe0 Muslim Companion quand sont les jours blancs"]},"Alexa, ask Muslim Companion when is the next Sunnah fast":{"does":"Le prochain je\xfbne de la Sunna : lundis et jeudis, jours blancs, Arafat, Achoura et les six jours de Chawwal.","say":["Alexa, demande \xe0 Muslim Companion quand est le prochain je\xfbne de la Sunna","Alexa, demande \xe0 Muslim Companion si je dois je\xfbner demain"]},"Alexa, ask Muslim Companion to turn on fasting reminders":{"does":"Un rappel apr\xe8s Isha la veille d\'un je\xfbne de la Sunna, via votre routine Muslim Companion.","say":["Alexa, demande \xe0 Muslim Companion d\'activer les rappels de je\xfbne","Alexa, demande \xe0 Muslim Companion de d\xe9sactiver les rappels de je\xfbne"]},"Alexa, ask Muslim Companion to play the morning adhkar":{"does":"Ayat al-Kursi, puis Al-Ikhlas, Al-Falaq et An-Nas trois fois chacune, r\xe9cit\xe9es.","say":["Alexa, demande \xe0 Muslim Companion de jouer les adhkar du matin","Alexa, demande \xe0 Muslim Companion de jouer les adhkar du soir"]},"Alexa, ask Muslim Companion to turn on morning and evening adhkar":{"does":"Joue les adhkar du matin apr\xe8s Fajr et ceux du soir apr\xe8s Asr chaque jour (ou Maghrib, r\xe9glable sur le tableau de bord).","say":["Alexa, demande \xe0 Muslim Companion d\'activer les adhkar du matin et du soir","Alexa, demande \xe0 Muslim Companion de d\xe9sactiver les adhkar du soir"]},"Alexa, ask Muslim Companion to start tasbih":{"does":"Compte le dhikr avec vous \xe0 un rythme doux. Sans dhikr pr\xe9cis\xe9, il guide le tasbih apr\xe8s la pri\xe8re : 33 SubhanAllah, 33 Alhamdulillah et 34 Allahu Akbar. Sur un Echo Show, touchez l\'\xe9cran pour compter.","say":["Alexa, demande \xe0 Muslim Companion de commencer le tasbih","Alexa, demande \xe0 Muslim Companion de compter 33 subhanallah"]},"Alexa, ask Muslim Companion for today\'s dua":{"does":"Une courte doua, un hadith ou un Nom d\'Allah du jour avec sa source, v\xe9rifi\xe9 par un savant avant publication.","say":["Alexa, demande \xe0 Muslim Companion la doua du jour","Alexa, demande \xe0 Muslim Companion le hadith du jour","Alexa, demande \xe0 Muslim Companion le nom d\'Allah du jour"],"soonNote":"Bient\xf4t : chaque doua, hadith et Nom est d\'abord v\xe9rifi\xe9 par un savant"},"Alexa, open Muslim Companion":{"does":"Lance la skill (elle joue l\'Adhan de la pri\xe8re en cours).","say":["Alexa, ouvre Muslim Companion"]},"Alexa, ask Muslim Companion for help":{"does":"Liste ce que vous pouvez demander.","say":["Alexa, demande de l\'aide \xe0 Muslim Companion"]},"Alexa, ask Muslim Companion to link my phone":{"does":"Relie cet Echo \xe0 votre compte Salat-e-Mustaqeem sur le t\xe9l\xe9phone avec le code \xe0 six chiffres de l\'app (Plus, puis Alexa), pour que votre progression de Hifz apparaisse sur le t\xe9l\xe9phone.","say":["Alexa, demande \xe0 Muslim Companion de relier mon t\xe9l\xe9phone","Alexa, demande \xe0 Muslim Companion de relier mon t\xe9l\xe9phone avec le code 123456"]}}}')}}]);